//! Script functions the engine runs (src/builtins.zig — every one the game's scripts
//! call), for the code editor's help: parameters with a sample value each (`?` —
//! optional) and what the function does. Each by its exe name (Classic); OG Script's
//! (`fighter::SetHp`) comes from the builtins' table (`ogsName`).

const std = @import("std");
const Allocator = std.mem.Allocator;
const Msg = @import("text.zig").Msg;

pub const Fn = struct {
    name: []const u8,
    /// `type name=sample, ?type name=sample`; samples hold no commas.
    params: []const u8,
    /// What each parameter is, in its order; what the function does.
    docs: []const Msg = &.{},
    doc: Msg,
};

pub const Param = struct {
    optional: bool,
    /// `int x`.
    decl: []const u8,
    sample: []const u8,
    /// What it is.
    doc: Msg = .{ .en = "", .ru = "" },
};

/// The function Classic (any case) or OG Script (`fighter::SetHp`) names `name`.
pub fn find(name: []const u8) ?*const Fn {
    for (&all, &ogs_names) |*f, o| if (std.ascii.eqlIgnoreCase(f.name, name) or std.mem.eql(u8, o, name)) return f;
    return null;
}

/// What OG Script calls `f` (`fighter::SetHp`, `print`); "": OG Script has none (`GetName`).
pub fn ogsName(f: *const Fn) []const u8 {
    return ogs_names[f - &all[0]];
}

/// `f` as code of that language calls it (`ogs`: OG Script).
pub fn shown(f: *const Fn, ogs: bool) []const u8 {
    return if (ogs) ogsName(f) else f.name;
}

/// The package of OG Script's name (`fighter`), "" the root's or none.
pub fn package(f: *const Fn) []const u8 {
    const n = ogsName(f);
    return n[0 .. std.mem.indexOf(u8, n, "::") orelse 0];
}

const ogs_names = blk: {
    @setEvalBranchQuota(400_000);
    var out: [all.len][]const u8 = undefined;
    for (&all, &out) |f, *o| o.* = for (@import("opengorky").builtins.table) |e| {
        if (std.mem.eql(u8, e[0], f.name)) break if (e[2].classic) "" else if (e[2].ogs.len > 0) e[2].ogs else e[0];
    } else "";
    break :blk out;
};

/// Description text `s` as shown: each backticked builtin (`LEVEL_Load`, by its exe name)
/// as code of that language calls it (`ogs`: OG Script's, the exe's where it has none),
/// unquoted; any other backticked word stays as written.
pub fn docText(a: Allocator, s: []const u8, ogs: bool) []const u8 {
    if (std.mem.indexOfScalar(u8, s, '`') == null) return s;
    var out: std.ArrayList(u8) = .empty;
    var rest = s;
    while (std.mem.indexOfScalar(u8, rest, '`')) |i| {
        const j = std.mem.indexOfScalarPos(u8, rest, i + 1, '`') orelse break;
        const w = rest[i + 1 .. j];
        const f = find(w);
        const n = if (f) |fp| (if (ogs and ogsName(fp).len > 0) ogsName(fp) else fp.name) else rest[i .. j + 1];
        out.appendSlice(a, rest[0..i]) catch return s;
        out.appendSlice(a, n) catch return s;
        rest = rest[j + 1 ..];
    }
    out.appendSlice(a, rest) catch return s;
    return out.items;
}

/// The parameters of `f` (up to `buf.len`).
pub fn params(f: *const Fn, buf: []Param) []Param {
    var n: usize = 0;
    if (f.params.len == 0) return buf[0..0];
    var it = std.mem.splitSequence(u8, f.params, ", ");
    while (it.next()) |p| {
        if (n == buf.len) break;
        const opt = p[0] == '?';
        const s = p[@intFromBool(opt)..];
        const eq = std.mem.indexOfScalar(u8, s, '=') orelse s.len;
        buf[n] = .{ .optional = opt, .decl = s[0..eq], .sample = if (eq < s.len) s[eq + 1 ..] else "0", .doc = if (n < f.docs.len) f.docs[n] else .{ .en = "", .ru = "" } };
        n += 1;
    }
    return buf[0..n];
}

/// The arguments a new call gets: the samples of the required parameters.
pub fn sampleArgs(a: Allocator, f: *const Fn) ![]const u8 {
    var buf: [12]Param = undefined;
    var out: std.ArrayList(u8) = .empty;
    for (params(f, &buf)) |p| {
        if (p.optional) break;
        if (out.items.len > 0) try out.appendSlice(a, ", ");
        try out.appendSlice(a, p.sample);
    }
    return out.items;
}

