    .{ .name = "ActorSetWalkAnimation", .params = "string anim=\"ladder_walk\", ?int reverse=0", .docs = &.{ .{ .en = "walk animation for the rest of the path (its speed too)", .ru = "анимация ходьбы на остаток пути (и её скорость)" }, .{ .en = "non-zero: plays it backwards", .ru = "не 0 — задом наперёд" } }, .doc = .{ .en = "Path script: the path's actor walks the rest of the path with this animation and its speed; non-zero reverse plays it backwards (going down a ladder).", .ru = "Скрипт пути: актёр идёт остаток пути с этой анимацией и её скоростью; ненулевой reverse проигрывает её задом наперёд (спуск по лестнице)." } },
    .{ .name = "ActorSetWalkSpeed", .params = "string anim=\"walk\", float speed=3.6", .docs = &.{ .{ .en = "walk animation whose speed is set", .ru = "анимация ходьбы, скорость которой задаётся" }, .{ .en = "world pixels per tick (a float)", .ru = "мировых пикселей за тик (дробное)" } }, .doc = .{ .en = "Sets the current actor's movement speed for a walk animation, in world pixels per tick; speed must be a float.", .ru = "Задаёт текущему актёру скорость движения для анимации ходьбы, в пикселях мира за тик; speed должен быть float." } },
    .{ .name = "AdjustAngle", .params = "float degrees=180.0", .docs = &.{.{ .en = "model orientation correction in degrees (a float)", .ru = "поправка ориентации модели в градусах (дробное)" }}, .doc = .{ .en = "Sets the current actor's model orientation correction in degrees; float only.", .ru = "Задаёт поправку ориентации модели текущего актёра в градусах; только float." } },
    .{ .name = "AIEnemyAppear", .params = "string name=\"01pr_sfinks2\", int x0=7, int y0=33, int x1=7, int y1=30", .docs = &.{ .{ .en = "enemy fighter to bring in", .ru = "вводимый вражеский боец" }, .{ .en = "start tile column (may be off the grid)", .ru = "столбец клетки старта (может быть вне сетки)" }, .{ .en = "start tile row", .ru = "строка клетки старта" }, .{ .en = "tile column it walks to", .ru = "столбец клетки, куда он идёт" }, .{ .en = "tile row it walks to", .ru = "строка клетки, куда он идёт" } }, .doc = .{ .en = "The enemy is placed at tile (x0, y0), often outside the grid, and walks to (x1, y1) at battle start.", .ru = "Враг ставится на клетку (x0, y0), часто за краем сетки, и в начале боя идёт на (x1, y1)." } },
    .{ .name = "AIFreeTile", .params = "int x=18, int y=6", .docs = &.{ .{ .en = "battle grid column", .ru = "столбец боевой сетки" }, .{ .en = "battle grid row", .ru = "строка боевой сетки" } }, .doc = .{ .en = "Returns true if the battle grid tile is inside the grid, open and unoccupied, otherwise false, also outside battle (1 and 0 in Classic).", .ru = "Возвращает true, если клетка боевой сетки внутри сетки, проходима и свободна, иначе false, вне боя тоже (в Classic 1 и 0)." } },
    .{ .name = "AIGetTurnNo", .params = "", .doc = .{ .en = "Returns the current battle turn number, or 0 outside battle.", .ru = "Возвращает номер текущего хода боя, вне боя 0." } },
    .{ .name = "BattleNearest", .params = "list tile, string side=\"hero\"", .docs = &.{ .{ .en = "tile [x, y]", .ru = "клетка [x, y]" }, .{ .en = "side: hero, enemy, neutral, civilian", .ru = "сторона: hero, enemy, neutral, civilian" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scoring: returns the live fighter of the side nearest to the tile (dx² + dy²), nil if none.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для оценки бойца: возвращает живого бойца стороны, ближайшего к клетке (dx² + dy²), nil — если нет." } },
    .{ .name = "AIGuardPoint", .params = "string fighter=\"03lr_jetelmer1\", int x=6, int y=2", .docs = &.{ .{ .en = "fighter that holds the tile", .ru = "боец, удерживающий клетку" }, .{ .en = "tile column to hold", .ru = "столбец удерживаемой клетки" }, .{ .en = "tile row to hold", .ru = "строка удерживаемой клетки" } }, .doc = .{ .en = "The fighter holds the battle tile (x, y) (sets ai_mode 3).", .ru = "Боец удерживает клетку боя (x, y) (ставит ai_mode 3)." } },
    .{ .name = "AITargetLock", .params = "string fighter=\"03lr_siner1\", string target=\"03lr_barrel1\"", .docs = &.{ .{ .en = "fighter that attacks only the target", .ru = "боец, атакующий только цель" }, .{ .en = "the only object it attacks", .ru = "единственный атакуемый объект" } }, .doc = .{ .en = "The fighter attacks only this target (sets ai_mode 1).", .ru = "Боец атакует только эту цель (ставит ai_mode 1)." } },
    .{ .name = "AllowWalkInArea", .params = "string area=\"kladka\", ?int floor=0", .docs = &.{ .{ .en = "area whose cells are opened", .ru = "область, клетки которой открываются" }, .{ .en = "walk map: 0 (.wm) or 1 (.wm2)", .ru = "карта ходьбы: 0 (.wm) или 1 (.wm2)" } }, .doc = .{ .en = "Opens the walk map cells inside the area polygon on floor 0 (.wm) or 1 (.wm2).", .ru = "Открывает клетки карты ходьбы внутри полигона зоны на этаже 0 (.wm) или 1 (.wm2)." } },
    .{ .name = "Ambient_New", .params = "string name=\"05lr_reactor_snd\", int x=320, int y=240, string wav=\"inside_reactor_loop.wav\"", .docs = &.{ .{ .en = "name of the new ambient object", .ru = "имя нового объекта звукового фона" }, .{ .en = "background x of the sound", .ru = "x звука на фоне" }, .{ .en = "background y of the sound", .ru = "y звука на фоне" }, .{ .en = "looping sound file", .ru = "зацикленный звуковой файл" } }, .doc = .{ .en = "Creates an ambient object: a looping sound at background point (x, y). Does nothing if an object with that name already exists.", .ru = "Создаёт ambient-объект: зацикленный звук в точке фона (x, y). Ничего не делает, если объект с таким именем уже есть." } },
    .{ .name = "AnyHero_HaveAmmoForWeapon", .params = "string weapon=\"su_rifle\"", .docs = &.{.{ .en = "weapon object whose ammo is looked for", .ru = "объект оружия, патроны к которому ищутся" }}, .doc = .{ .en = "Returns true if any party hero has ammo for the weapon (same test as `Actor_HaveAmmoForWeapon`), otherwise false (1 and 0 in Classic).", .ru = "Возвращает true, если у кого-то из героев отряда есть патроны к оружию (та же проверка, что в `Actor_HaveAmmoForWeapon`), иначе false (в Classic 1 и 0)." } },
    .{ .name = "AnyHero_HaveItem", .params = "string item=\"04c_adv_rocket\"", .docs = &.{.{ .en = "item object whose owner is tested", .ru = "предмет, владелец которого проверяется" }}, .doc = .{ .en = "Returns true if the item's owner is a party hero, otherwise false (1 and 0 in Classic).", .ru = "Возвращает true, если владелец предмета — герой отряда, иначе false (в Classic 1 и 0)." } },
    .{ .name = "AttachActors", .params = "string parent=\"ponton\", string actor=\"Sullivan\", float a=0.0, float b=10.0, float c=5.0, float angle=0.0", .docs = &.{ .{ .en = "object the actor rides", .ru = "объект, на котором едет актёр" }, .{ .en = "actor attached", .ru = "прикрепляемый актёр" }, .{ .en = "offset along the parent's first horizontal axis (float)", .ru = "смещение по первой горизонтальной оси родителя (дробное)" }, .{ .en = "offset along the parent's second horizontal axis (float)", .ru = "смещение по второй горизонтальной оси родителя (дробное)" }, .{ .en = "height offset (float)", .ru = "смещение по высоте (дробное)" }, .{ .en = "added to the parent's angle (float)", .ru = "прибавляется к углу родителя (дробное)" } }, .doc = .{ .en = "Attaches an actor to the parent at the given offset, so it moves with the parent: a and b horizontal in the parent's axes, c height, world units; angle is added to the parent's. All four must be floats. Not used by the game's scripts.", .ru = "Прикрепляет актёра к родителю с заданным смещением, и он движется вместе с ним: a и b по горизонтали в осях родителя, c по высоте, в мировых единицах; angle прибавляется к углу родителя. Все четыре должны быть float. В скриптах игры не используется." } },
    .{ .name = "AttachActorsByLink", .params = "string parent=\"ponton\", string actor=\"Sullivan\", string point=\"Sullivan\"", .docs = &.{ .{ .en = "object whose mesh has the link point", .ru = "объект, на меше которого точка связи" }, .{ .en = "actor attached", .ru = "прикрепляемый актёр" }, .{ .en = "link point of the parent's mesh", .ru = "точка связи меша родителя" } }, .doc = .{ .en = "Attaches an actor to a link point of the parent's mesh, so it moves with the parent. Does nothing if the point is missing.", .ru = "Прикрепляет актёра к точке связи меша родителя, и он движется вместе с ним. Ничего не делает, если точки нет." } },
    .{ .name = "AVI_Play", .params = "string file=\"Stingermus.avi\", int x=0, int y=60, int double=1", .docs = &.{ .{ .en = "video file of the avi folder", .ru = "видеофайл из папки avi" }, .{ .en = "screen x of the video", .ru = "x видео на экране" }, .{ .en = "screen y of the video", .ru = "y видео на экране" }, .{ .en = "1: double size", .ru = "1 — двойной размер" } }, .doc = .{ .en = "Plays a video (e.g. before a boss battle) at screen position (x, y); double 1 shows it at double size.", .ru = "Проигрывает видео (например, перед боем с боссом) в позиции экрана (x, y); double 1 показывает его в двойном размере." } },
    .{ .name = "BattleAddVar", .params = "string name=\"grandma_kids\", any delta=1", .docs = &.{ .{ .en = "battle variable", .ru = "переменная боя" }, .{ .en = "added to it (an unset one is 0)", .ru = "что прибавить (незаданная — 0)" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: adds to the battle variable and returns the new value; every fighter's OnVar(name, value) hears it.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: прибавляет к переменной боя и возвращает новое значение; его слышит OnVar(name, value) каждого бойца." } },
    .{ .name = "BattleGetVar", .params = "string name=\"grandma_kids\"", .docs = &.{.{ .en = "battle variable", .ru = "переменная боя" }}, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: the battle variable's value (nil when unset); the variables live until the battle ends.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: значение переменной боя (nil, если не задана); переменные живут до конца боя." } },
    .{ .name = "BattleLose", .params = "", .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: the battle ends lost, as when the heroes fall (game over), at its next end check (after the current action). 1, or 0 outside a battle.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: бой заканчивается поражением, как при гибели героев (конец игры), при следующей проверке конца боя (после текущего действия). 1 или 0 вне боя." } },
    .{ .name = "BattleSetVar", .params = "string name=\"grandma_kids\", any value=0", .docs = &.{ .{ .en = "battle variable", .ru = "переменная боя" }, .{ .en = "its new value", .ru = "новое значение" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: sets the battle variable; every fighter's OnVar(name, value) hears it.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: задаёт переменную боя; её слышит OnVar(name, value) каждого бойца." } },
    .{ .name = "BattleSpawnCivilian", .params = "character fighter=\"ft_hornet\", int x=3, int y=2, ?string ai=\"dummy\"", .docs = &.{ .{ .en = "fighter class as the rules name it (ft_hornet) or a .ftr file; in an OpenGorky project also a fighter archetype (~c\"characters::grandma\")", .ru = "класс бойца, как его называют правила (ft_hornet), или файл .ftr; в проекте OpenGorky также архетип бойца (~c\"characters::grandma\")" }, .{ .en = "tile column (a big fighter's left)", .ru = "столбец клетки (у большого бойца — левый)" }, .{ .en = "tile row (a big fighter's top)", .ru = "строка клетки (у большого бойца — верхняя)" }, .{ .en = "its AI: \"dummy\" (left out) stands and does nothing, \"normal\" its class's AI", .ru = "его ИИ: \"dummy\" (по умолчанию) стоит и ничего не делает, \"normal\" — ИИ его класса" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: puts a new fighter of neither side on a free tile: both sides can hit it, it acts by its AI on the enemies' turn and counts neither for victory nor for defeat (`BattleLose` in its OnDeath makes it count). It gets its abilities and OnSpawn; without its own weapons, copies of those a fighter of its class holds. Its object name, or nil (no such class, tile out of the grid or taken).", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: ставит на свободную клетку нового бойца, не принадлежащего ни одной стороне: его могут бить обе стороны, он действует своим ИИ в ход врагов и не учитывается ни для победы, ни для поражения (`BattleLose` в его OnDeath это меняет). Он получает свои способности и OnSpawn; без своего оружия — копии оружия бойца того же класса. Возвращает имя объекта или nil (нет такого класса, клетка вне сетки или занята)." } },
    .{ .name = "BattleSpawnEnemy", .params = "character fighter=\"ft_hornet\", int x=3, int y=2", .docs = &.{ .{ .en = "fighter class as the rules name it (ft_hornet) or a .ftr file; in an OpenGorky project also a fighter archetype (~c\"characters::grandma\")", .ru = "класс бойца, как его называют правила (ft_hornet), или файл .ftr; в проекте OpenGorky также архетип бойца (~c\"characters::grandma\")" }, .{ .en = "tile column (a big fighter's left)", .ru = "столбец клетки (у большого бойца — левый)" }, .{ .en = "tile row (a big fighter's top)", .ru = "строка клетки (у большого бойца — верхняя)" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: puts a new fighter on the enemies' side on a free tile; it acts by AI as any enemy. It gets its abilities and OnSpawn; without its own weapons, copies of those a fighter of its class holds. Its object name, or nil (no such class, tile out of the grid or taken).", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: ставит на свободную клетку нового бойца на стороне врагов; он ходит под ИИ, как любой враг. Он получает свои способности и OnSpawn; без своего оружия — копии оружия бойца того же класса. Возвращает имя объекта или nil (нет такого класса, клетка вне сетки или занята)." } },
    .{ .name = "BattleSpawnHero", .params = "character fighter=\"ft_hornet\", int x=3, int y=2", .docs = &.{ .{ .en = "fighter class as the rules name it (ft_hornet) or a .ftr file; in an OpenGorky project also a fighter archetype (~c\"characters::grandma\")", .ru = "класс бойца, как его называют правила (ft_hornet), или файл .ftr; в проекте OpenGorky также архетип бойца (~c\"characters::grandma\")" }, .{ .en = "tile column (a big fighter's left)", .ru = "столбец клетки (у большого бойца — левый)" }, .{ .en = "tile row (a big fighter's top)", .ru = "строка клетки (у большого бойца — верхняя)" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: puts a new fighter on the heroes' side on a free tile; the player selects it and gives it turns as a hero, for this battle only (it does not join the party). It gets its abilities and OnSpawn; without its own weapons, copies of those a fighter of its class holds. Its object name, or nil (no such class, tile out of the grid or taken).", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: ставит на свободную клетку нового бойца на стороне героев; игрок выбирает его и ходит им, как героем, только в этом бою (в отряд он не вступает). Он получает свои способности и OnSpawn; без своего оружия — копии оружия бойца того же класса. Возвращает имя объекта или nil (нет такого класса, клетка вне сетки или занята)." } },
    .{ .name = "BattleWin", .params = "", .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: the battle ends won, as when the last enemy dies (victory), at its next end check (after the current action). 1, or 0 outside a battle.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: бой заканчивается победой, как при гибели последнего врага, при следующей проверке конца боя (после текущего действия). 1 или 0 вне боя." } },
    .{ .name = "DeactivateLink", .params = "string point=\"pila prawa\"", .docs = &.{.{ .en = "link point whose mesh is taken off", .ru = "точка связи, с которой снять меш" }}, .doc = .{ .en = "Takes the mesh off a link point of the current actor (the opposite of `ActivateLink`). Not used by the game's scripts.", .ru = "Снимает меш с точки связи текущего актёра (обратное `ActivateLink`). В скриптах игры не используется." } },
    .{ .name = "DeleteObject", .params = "string object=\"Slavsky\"", .docs = &.{.{ .en = "object to disable and mark deleted", .ru = "объект, который отключить и пометить удалённым" }}, .doc = .{ .en = "Disables the named object and marks it deleted.", .ru = "Выключает указанный объект и помечает его удалённым." } },
    .{ .name = "DetachActorsFrom", .params = "string parent=\"ponton\"", .docs = &.{.{ .en = "object whose attached actors are released", .ru = "объект, прикреплённые актёры которого освобождаются" }}, .doc = .{ .en = "Detaches all actors attached to the parent and clears their model offsets.", .ru = "Открепляет всех актёров, прикреплённых к родителю, и сбрасывает смещения их моделей." } },
    .{ .name = "DialogInit", .params = "string name=\"lab-after_teleport\", string file=\"lab-after_teleport.dlg\"", .docs = &.{ .{ .en = "dialog name", .ru = "имя диалога" }, .{ .en = ".dlg file with its lines", .ru = "файл .dlg с репликами" } }, .doc = .{ .en = "Shows a whole dialog from the .dlg file, line by line.", .ru = "Показывает весь диалог из файла .dlg, реплику за репликой." } },
    .{ .name = "Dialog", .params = "dialog dialog=\"lab-after_teleport\"", .docs = &.{.{ .en = "the dialog (~d\"lab-after_teleport\": a dialog block of the project)", .ru = "диалог (~d\"lab-after_teleport\": блок dialog проекта)" }}, .doc = .{ .en = "OpenGorky only (the original exe has DialogInit(name, file)): shows a whole dialog, line by line.", .ru = "Только OpenGorky (в оригинальном exe — DialogInit(имя, файл)): показывает весь диалог, реплику за репликой." } },
    .{ .name = "Disable", .params = "", .doc = .{ .en = "Disables the current actor (the one whose script runs).", .ru = "Выключает текущего актёра (того, чей скрипт выполняется)." } },
    .{ .name = "DisableHeroes", .params = "", .doc = .{ .en = "Disables every party hero except the selected one. Called right after `LEVEL_Load` it applies to the new level.", .ru = "Выключает всех героев отряда, кроме выбранного. Сразу после `LEVEL_Load` действует на новом уровне." } },
    .{ .name = "DisableObject", .params = "string object=\"Trantigne\"", .docs = &.{.{ .en = "object to disable", .ru = "отключаемый объект" }}, .doc = .{ .en = "Disables the named object; it stays in the level and can be enabled again.", .ru = "Выключает указанный объект; он остаётся на уровне, его можно включить снова." } },
    .{ .name = "EqualsIgnoreCase", .params = "string a=\"Sullivan\", string b=\"sullivan\"", .docs = &.{ .{ .en = "first string", .ru = "первая строка" }, .{ .en = "second string", .ru = "вторая строка" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function): true if the strings are equal, case aside (Latin letters), else false. OG Script's == minds case; Classic compares this way with `s_stricmp`.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет): true, если строки равны без учёта регистра (латинские буквы), иначе false. == в OG Script учитывает регистр; в Classic так сравнивает `s_stricmp`." } },
    .{ .name = "EnableHeroes", .params = "", .doc = .{ .en = "Enables all heroes that do not have outside_party set (party members).", .ru = "Включает всех героев без флага outside_party (членов отряда)." } },
    .{ .name = "EnableObject", .params = "string object=\"01pr_sfinks2\"", .docs = &.{.{ .en = "object to enable", .ru = "включаемый объект" }}, .doc = .{ .en = "Enables the named object (it becomes active and visible again).", .ru = "Включает указанный объект (он снова активен и виден)." } },
    .{ .name = "EndTurnGlobal", .params = "", .doc = .{ .en = "Ends the current side's turn in battle.", .ru = "Завершает ход текущей стороны в бою." } },
    .{ .name = "Emit", .params = "string event=\"child_died\", ?any args...=host", .docs = &.{ .{ .en = "event name", .ru = "имя события" }, .{ .en = "values passed to the handlers (any number, objects as they are)", .ru = "значения для обработчиков (сколько угодно, объекты как есть)" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities and other components: calls the handler of every component subscribed to the event (`Subscribe`), in subscription order, with the values; returns how many were called. A handler may `Emit` again, up to 8 deep. In battle the log gets emit <event> n=<handlers>.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца и других компонентов: вызывает обработчик каждого компонента, подписанного на событие (`Subscribe`), в порядке подписки, с этими значениями; возвращает, сколько вызвано. Обработчик может сам вызвать `Emit`, не глубже 8. В бою в лог пишется emit <событие> n=<обработчиков>." } },
    .{ .name = "FadeIn", .params = "", .doc = .{ .en = "Fades the screen in from black. After `LEVEL_Load` it applies to the new level.", .ru = "Плавно проявляет экран из чёрного. После `LEVEL_Load` действует на новом уровне." } },
    .{ .name = "FighterGetHp", .params = "string fighter=\"Sullivan\"", .docs = &.{.{ .en = "fighter whose hit points are read", .ru = "боец, здоровье которого читается" }}, .doc = .{ .en = "Returns the fighter's current hit points (0 if the object is not found).", .ru = "Возвращает текущие очки здоровья бойца (0, если объект не найден)." } },
    .{ .name = "FighterSetHp", .params = "string fighter=\"Sullivan\", int hp=50", .docs = &.{ .{ .en = "fighter whose hit points are set", .ru = "боец, здоровье которого задаётся" }, .{ .en = "new hit points (an integer)", .ru = "новое здоровье (целое)" } }, .doc = .{ .en = "Sets the fighter's hit points. Only an integer value is accepted; there is no upper clamp. OpenGorky: a call from OG Script in battle is written to the battle log.", .ru = "Задаёт очки здоровья бойца. Принимается только целое число; верхнего предела нет. OpenGorky: вызов из OG Script в бою пишется в лог боя." } },
    .{ .name = "FighterSetLevel", .params = "string fighter=\"Slavsky\", int level=5", .docs = &.{ .{ .en = "fighter whose level is set", .ru = "боец, уровень которого задаётся" }, .{ .en = "new level (experience set to its threshold)", .ru = "новый уровень (опыт — его порог)" } }, .doc = .{ .en = "Sets the fighter's level and its experience to that level's threshold.", .ru = "Задаёт бойцу уровень и опыт, равный порогу этого уровня." } },
    .{ .name = "FighterSetWeaponSkillLevel", .params = "string fighter=\"Slavsky\", int weapon=76, int level=8", .docs = &.{ .{ .en = "fighter whose skill is set", .ru = "боец, навык которого задаётся" }, .{ .en = "weapon classic_id", .ru = "classic_id оружия" }, .{ .en = "skill level", .ru = "уровень навыка" } }, .doc = .{ .en = "Sets the fighter's skill level for the weapon with this classic_id, adding the skill if missing.", .ru = "Задаёт бойцу уровень владения оружием с этим classic_id; если навыка нет, добавляет его." } },
    .{ .name = "FighterAddState", .params = "string who=\"Sullivan\", string state=\"rage\", ?int turns=2", .docs = &.{ .{ .en = "fighter (an object or its name)", .ru = "боец (объект или его имя)" }, .{ .en = "sleep, freeze, burn, gas, soak, defend or rage", .ru = "sleep, freeze, burn, gas, soak, defend или rage" }, .{ .en = "for how many turns (rage: actions); 1 if left out", .ru = "на сколько ходов (rage — действий); без него 1" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: puts the fighter in a state for some turns (1 done, 0: no such state).", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: даёт бойцу состояние на несколько ходов (1 — сделано, 0 — нет такого состояния)." } },
    .{ .name = "FighterAlive", .params = "string who=\"Sullivan\"", .docs = &.{.{ .en = "fighter (an object or its name)", .ru = "боец (объект или его имя)" }}, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: true while the fighter fights on, else false (1 and 0 in Classic).", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: true, пока боец в бою, иначе false (в Classic 1 и 0)." } },
    .{ .name = "FighterDamage", .params = "string who=\"Garcia\", int amount=5, ?string kind=\"reflect\", ?string from=\"Sullivan\"", .docs = &.{ .{ .en = "fighter (an object or its name)", .ru = "боец (объект или его имя)" }, .{ .en = "damage", .ru = "урон" }, .{ .en = "what it is, for the battle log", .ru = "что это, для лога боя" }, .{ .en = "on whose behalf (its killer if it dies)", .ru = "от чьего имени (убийца, если погибнет)" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: deals damage to the fighter at once, with no armour and no OnHit (a reflection is not reflected back).", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: сразу наносит бойцу урон, без брони и без OnHit (отражённый урон не отражается обратно)." } },
    .{ .name = "FighterGetLastAttacker", .params = "string who=\"Sullivan\"", .docs = &.{.{ .en = "fighter (an object or its name)", .ru = "боец (объект или его имя)" }}, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: the fighter that hit it last, or nil.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: боец, который ударил его последним, или nil." } },
    .{ .name = "FighterNative", .params = "string who=\"messiah\", string name=\"Guard\"", .docs = &.{ .{ .en = "fighter (an object or its name)", .ru = "боец (объект или его имя)" }, .{ .en = "the native component (Guard, OpenFrom, Stand…)", .ru = "нативный компонент (Guard, OpenFrom, Stand…)" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripts in and out of battle: its native component of that name, whose params are its variables (fighter::Native(host, \"Guard\").div = 4 changes its defence from then on), or nil.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптов бойца в бою и вне его: его нативный компонент с этим именем, параметры которого — его переменные (fighter::Native(host, \"Guard\").div = 4 меняет его защиту с этого момента), или nil." } },
    .{ .name = "FighterPopup", .params = "string who=\"Sullivan\", string text=\"Rage!\"", .docs = &.{ .{ .en = "fighter (an object or its name)", .ru = "боец (объект или его имя)" }, .{ .en = "text shown", .ru = "показываемый текст" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: a text rising over the fighter, as \"Miss\".", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: текст, всплывающий над бойцом, как «Промах»." } },
    .{ .name = "FighterTransform", .params = "string who=\"Garcia\", string into=\"ft_hornet\", ?string anim=\"\", ?string idle=\"\", ?sound sound=\"\"", .docs = &.{ .{ .en = "fighter (an object or its name)", .ru = "боец (объект или его имя)" }, .{ .en = "new class as the rules name it (ft_hornet) or a class file", .ru = "новый класс, как его называют правила (ft_hornet), или файл класса" }, .{ .en = "its model (mesh); empty: the class's", .ru = "его модель (meshFile); пусто — модель класса" }, .{ .en = "animation played once after it", .ru = "анимация, которая проиграется один раз после" }, .{ .en = "sound of the transformation", .ru = "звук превращения" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: the fighter turns into another class, as the Transform row's (freed, a glow, then the new class's values and model); its abilities, native and scripted, come from the new class's row (a scripted one in both rows stays as it is); the health it has then stays. 1, or 0 (no such fighter or class).", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: боец превращается в другой класс, как в строке Transform (освобождается, свечение, затем значения и модель нового класса); способности, нативные и скриптовые, — из строки нового класса (скриптовая, которая есть в обеих строках, остаётся как есть); здоровье, которое у него к тому времени, сохраняется. 1 или 0 (нет такого бойца или класса)." } },
    .{ .name = "FighterSetTarget", .params = "string who=\"grandma\", string target=\"Sullivan\"", .docs = &.{ .{ .en = "fighter (an object or its name)", .ru = "боец (объект или его имя)" }, .{ .en = "whom it strikes above all", .ru = "кого бить в первую очередь" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: the fighter's AI strikes the target above all (as Grandma her child's killer).", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: ИИ бойца бьёт цель в первую очередь (как Бабушка — убийцу своего ребёнка)." } },
    .{ .name = "FighterSide", .params = "string who=\"Sullivan\"", .docs = &.{.{ .en = "fighter (an object or its name)", .ru = "боец (объект или его имя)" }}, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities in battle: \"hero\", \"enemy\", \"neutral\" (an obstacle), \"civilian\" (of neither side) or \"\" (not in the battle).", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца в бою: \"hero\", \"enemy\", \"neutral\" (препятствие), \"civilian\" (ни на чьей стороне) или \"\" (не в бою)." } },
    .{ .name = "ForbidWalkInArea", .params = "string area=\"ciuch_blokada\", ?int floor=0", .docs = &.{ .{ .en = "area whose cells are blocked", .ru = "область, клетки которой закрываются" }, .{ .en = "walk map: 0 (.wm) or 1 (.wm2)", .ru = "карта ходьбы: 0 (.wm) или 1 (.wm2)" } }, .doc = .{ .en = "Blocks the walk map cells inside the area polygon on floor 0 (.wm) or 1 (.wm2).", .ru = "Закрывает клетки карты ходьбы внутри полигона зоны на этаже 0 (.wm) или 1 (.wm2)." } },
    .{ .name = "GetName", .params = "", .doc = .{ .en = "Returns the name of the object whose script is running.", .ru = "Возвращает имя объекта, чей скрипт выполняется." } },
    .{ .name = "GetNameID", .params = "string object=\"Lucy\"", .docs = &.{.{ .en = "object whose classic_id is read; \"this\": the caller", .ru = "объект, classic_id которого читается; \"this\" — вызывающий" }}, .doc = .{ .en = "Returns the object's classic_id (heroes: 20 Sullivan, 21 Ovitz, 22 Trantigne, 24 Lucy); \"this\" means the caller. Returns -1 if there is no such object.", .ru = "Возвращает classic_id объекта (герои: 20 Sullivan, 21 Ovitz, 22 Trantigne, 24 Lucy); \"this\" — вызывающий. Возвращает -1, если объекта нет." } },
    .{ .name = "GetClass", .params = "string object=\"this\"", .docs = &.{.{ .en = "object whose class is read; \"this\": the caller", .ru = "объект, класс которого читается; \"this\" — вызывающий" }}, .doc = .{ .en = "OpenGorky only (the original exe has no such function): the object's class as the rules name it (an OpenGorky project's: its archetype's path, \"weapons::riffle\", \"characters::hornet\"), for hooks; \"\" if there is no such object.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет): класс объекта, как его называют правила (в проекте OpenGorky — путь архетипа: \"weapons::riffle\", \"characters::hornet\"), для хуков; \"\", если объекта нет." } },
    .{ .name = "GetLevel", .params = "", .doc = .{ .en = "OpenGorky only (the original exe has no such function): the current level's name (\"05_laboratory\"), for hooks.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет): имя текущего уровня (\"05_laboratory\"), для хуков." } },
    .{ .name = "GO_RunFun", .params = "string object=\"04_city\", string function=\"EnableFactoryOut\"", .docs = &.{ .{ .en = "object whose script holds the function (any loaded level)", .ru = "объект, в скрипте которого функция (любого загруженного уровня)" }, .{ .en = "function to call; further arguments are passed on", .ru = "вызываемая функция; следующие аргументы передаются ей" } }, .doc = .{ .en = "Calls the object's function (extra arguments are passed on), also on objects of other loaded levels. Returns the function's result, or 0.", .ru = "Вызывает функцию объекта (дополнительные аргументы передаются дальше), в том числе у объектов других загруженных уровней. Возвращает результат функции или 0." } },
    .{ .name = "GUI_Disable", .params = "int mode=2", .docs = &.{.{ .en = "0 normal, 1 panorama off, 2 scene mode", .ru = "0 — обычный, 1 — без панорамы, 2 — режим сценки" }}, .doc = .{ .en = "0 returns to normal mode, 1 turns panorama off, 2 enters scene mode (no player control, automatic camera).", .ru = "0 возвращает обычный режим, 1 выключает панораму, 2 включает режим сцены (без управления, автокамера)." } },
    .{ .name = "GUI_GetSelectedHero", .params = "", .doc = .{ .en = "Returns the name of the currently selected hero.", .ru = "Возвращает имя выбранного сейчас героя." } },
    .{ .name = "GUI_IsHero", .params = "string name=\"Slavsky\"", .docs = &.{.{ .en = "hero tested", .ru = "проверяемый герой" }}, .doc = .{ .en = "Returns true if the hero is in the party (on the panel) and enabled, otherwise false (1 and 0 in Classic).", .ru = "Возвращает true, если герой в отряде (на панели) и включён, иначе false (в Classic 1 и 0)." } },
    .{ .name = "GUI_Panorama", .params = "int on=1", .docs = &.{.{ .en = "non-zero: on, 0: off", .ru = "не 0 — включить, 0 — выключить" }}, .doc = .{ .en = "Turns panorama mode on (non-zero) or off (0).", .ru = "Включает (не 0) или выключает (0) режим панорамы." } },
    .{ .name = "GUI_SelectMode", .params = "string mode=\"GUI_Staging\"", .docs = &.{.{ .en = "\"GUI_Staging\" or \"GUI_SafeBox\"", .ru = "\"GUI_Staging\" или \"GUI_SafeBox\"" }}, .doc = .{ .en = "\"GUI_Staging\" starts the battle with the enemy turn (enemies walk in); \"GUI_SafeBox\" opens the safe keypad for the calling area.", .ru = "\"GUI_Staging\" начинает бой с хода врагов (они входят на поле); \"GUI_SafeBox\" открывает кодовый замок сейфа для вызывающей зоны." } },
    .{ .name = "HERO_EnableEnumerate", .params = "string hero=\"MacFadden\", int on=1", .docs = &.{ .{ .en = "hero joining or leaving", .ru = "герой, который входит в отряд или выходит" }, .{ .en = "1: joins the party, 0: leaves", .ru = "1 — в отряд, 0 — из отряда" } }, .doc = .{ .en = "The hero joins (1) or leaves (0) the party; sets outside_party to the opposite.", .ru = "Герой вступает в отряд (1) или уходит из него (0); outside_party ставится в обратное значение." } },
    .{ .name = "HeroInArea", .params = "string area=\"fight_01\"", .docs = &.{.{ .en = "area polygon tested", .ru = "проверяемая область" }}, .doc = .{ .en = "Returns true if any enabled, placed hero stands inside the area polygon (by background point), otherwise false (1 and 0 in Classic).", .ru = "Возвращает true, если хоть один включённый и размещённый герой стоит внутри полигона зоны (по точке на фоне), иначе false (в Classic 1 и 0)." } },
    .{ .name = "IsHere", .params = "any x=@Sullivan", .docs = &.{.{ .en = "a reference (any other value: false)", .ru = "ссылка (любое другое значение — false)" }}, .doc = .{ .en = "OpenGorky only (the original exe has no such function): true if the reference is to an object of this location (a deleted one too), false if to one of another location (a hero's var holding a 01_port object, carried to the next location: its fields and methods are nil until the party is back there) or not a reference.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет): true, если ссылка на объект этой локации (в том числе удалённый), false — на объект другой локации (переменная героя со ссылкой на объект 01_port, перенесённая в следующую локацию: его поля и методы дают nil, пока отряд не вернётся туда) или не ссылка." } },
    .{ .name = "IsObject", .params = "string name=\"Sullivan\"", .docs = &.{.{ .en = "object name looked for", .ru = "искомое имя объекта" }}, .doc = .{ .en = "Returns true if an object with this name exists, else false (1 and 0 in Classic).", .ru = "Возвращает true, если объект с таким именем существует, иначе false (в Classic 1 и 0)." } },
    .{ .name = "Item_Animation", .params = "string item=\"this\", string anim=\"box\", int reverse=0", .docs = &.{ .{ .en = "item whose model animates; \"this\": the caller", .ru = "предмет, модель которого анимируется; \"this\" — вызывающий" }, .{ .en = "model animation name", .ru = "имя анимации модели" }, .{ .en = "1: plays it backwards", .ru = "1 — задом наперёд" } }, .doc = .{ .en = "Plays the item model's animation once and holds the last frame; reverse 1 plays it backwards (a box closes with \"box\" reversed).", .ru = "Проигрывает анимацию модели предмета один раз и держит последний кадр; reverse 1 играет её задом наперёд (ящик закрывается обратной \"box\")." } },
    .{ .name = "Item_DisableWalkCircle", .params = "string item=\"this\"", .docs = &.{.{ .en = "item whose walk_block_radius blocks walk cells", .ru = "предмет, радиус которого закрывает клетки" }}, .doc = .{ .en = "Blocks the .wm walk cells within the item's walk_block_radius (background pixels, if 2 or more).", .ru = "Закрывает клетки .wm в пределах walk_block_radius предмета (пиксели фона, если не меньше 2)." } },
    .{ .name = "Item_EnableWalkCircle", .params = "string item=\"this\"", .docs = &.{.{ .en = "item whose walk_block_radius opens walk cells", .ru = "предмет, радиус которого открывает клетки" }}, .doc = .{ .en = "Makes the .wm walk cells within the item's walk_block_radius (background pixels, if 2 or more) walkable.", .ru = "Делает проходимыми клетки .wm в пределах walk_block_radius предмета (пиксели фона, если не меньше 2)." } },
    .{ .name = "Item_GetNameID", .params = "string item=\"03mf_matrix\"", .docs = &.{.{ .en = "item whose classic_id is read", .ru = "предмет, classic_id которого читается" }}, .doc = .{ .en = "Returns the item's classic_id, or -1 if the object is missing or not an item.", .ru = "Возвращает classic_id предмета или -1, если объекта нет или это не предмет." } },
    .{ .name = "Item_GetPlace", .params = "string item=\"03mf_matrix\"", .docs = &.{.{ .en = "item whose place is read", .ru = "предмет, место которого читается" }}, .doc = .{ .en = "Returns the item's place (0 = ground), or -1 if the object is missing or not an item.", .ru = "Возвращает место предмета (0 = земля) или -1, если объекта нет или это не предмет." } },
    .{ .name = "Item_GetType", .params = "string item=\"decha\"", .docs = &.{.{ .en = "item whose type is read", .ru = "предмет, тип которого читается" }}, .doc = .{ .en = "Returns the item's kind (`kind`; a weapon's `damage_kind`, as the exe), or -1 if the object is missing or not an item.", .ru = "Возвращает вид предмета (`kind`; у оружия — `damage_kind`, как в exe) или -1, если объекта нет или это не предмет." } },
    .{ .name = "Item_New", .params = "string name=\"su_am_pistol\", string class=\"ca_pistolammo.s\", ?string owner=\"Sullivan\", ?int count=12", .docs = &.{ .{ .en = "name of the new item object", .ru = "имя нового предмета" }, .{ .en = "class script it is made of", .ru = "скрипт класса, из которого он создаётся" }, .{ .en = "owner's name, or a number: the counter", .ru = "имя владельца или число — счётчик" }, .{ .en = "counter (e.g. ammo amount)", .ru = "счётчик (например, патронов)" } }, .doc = .{ .en = "Creates an item object of the class. A string third argument is the owner, a number is the counter; the fourth argument, if any, is the counter (e.g. ammo amount).", .ru = "Создаёт предмет этого класса. Третий аргумент-строка это владелец, число это счётчик; четвёртый аргумент, если есть, это счётчик (например, число патронов)." } },
    .{ .name = "Item_SetAngle", .params = "string item=\"tlen\", float angle=1.57", .docs = &.{ .{ .en = "item to turn", .ru = "поворачиваемый предмет" }, .{ .en = "rotation in radians", .ru = "поворот в радианах" } }, .doc = .{ .en = "Sets the item's rotation angle in radians.", .ru = "Задаёт угол поворота предмета в радианах." } },
    .{ .name = "Item_SetFuncID", .params = "string item=\"tlen\", any action=\"walk\"", .docs = &.{ .{ .en = "item whose action is set", .ru = "предмет, действие которого задаётся" }, .{ .en = "its new rules Action row: its name (\"Close\", \"walk\", \"none\") or number", .ru = "новая строка Action правил: её имя (\"Close\", \"walk\", \"none\") или номер" } }, .doc = .{ .en = "Sets the item's action: a rules Action row by name or number (its field action).", .ru = "Задаёт предмету действие: имя строки Action правил (\"Close\", \"walk\", \"none\") или её номер (его поле action)." } },
    .{ .name = "ActionId", .params = "string name=\"walk\"", .docs = &.{.{ .en = "a rules Action row's name; walk, none", .ru = "имя строки Action правил; walk, none" }}, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's comparison of an action field: the number of action `name` (walk −1, none 0), 0 if none.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для сравнения поля action: номер действия по имени (walk −1, none 0), 0 — нет такого." } },
    .{ .name = "Item_SetNameID", .params = "string item=\"decha\", int classic_id=-1", .docs = &.{ .{ .en = "item whose classic_id is set", .ru = "предмет, classic_id которого задаётся" }, .{ .en = "new classic_id", .ru = "новый classic_id" } }, .doc = .{ .en = "Sets the item's classic_id (its name/type id).", .ru = "Задаёт предмету classic_id (идентификатор имени/типа)." } },
    .{ .name = "Item_SetPlace", .params = "string item=\"tlen\", int place=0", .docs = &.{ .{ .en = "item whose place is set", .ru = "предмет, место которого задаётся" }, .{ .en = "new place; 0 (ground) drops it from its owner", .ru = "новое место; 0 (земля) — снять с владельца" } }, .doc = .{ .en = "Sets the item's place; 0 (ground) on an owned item clears its owner, and a hero holding it in hand goes unarmed.", .ru = "Задаёт место предмета; 0 (земля) у предмета с владельцем снимает владельца, а герой, державший его в руке, остаётся без оружия." } },
    .{ .name = "Item_SetPos", .params = "string item=\"decha\", float x=1455.0, float y=-394.0, float z=128.0", .docs = &.{ .{ .en = "item to move", .ru = "перемещаемый предмет" }, .{ .en = "world x, or \"area\" for the area form", .ru = "мировой x или \"area\" для формы с областью" }, .{ .en = "world y, or the area point (-1: control point)", .ru = "мировой y или точка области (-1 — контрольная)" }, .{ .en = "world z, or the height over the floor", .ru = "мировой z или высота над полом" } }, .doc = .{ .en = "Moves the item to world coordinates. Alternative form (item, \"area\", point, z): puts it at an area polygon point (-1 = control point) on the floor raised by z.", .ru = "Переносит предмет в мировые координаты. Другая форма (item, \"area\", point, z): ставит его в точку полигона зоны (-1 = контрольная точка) на полу, поднятым на z." } },
    .{ .name = "Item_SetVisible", .params = "string item=\"Nota2\", int visible=1", .docs = &.{ .{ .en = "item to show or hide", .ru = "показываемый или скрываемый предмет" }, .{ .en = "1: shown, 0: hidden", .ru = "1 — показать, 0 — скрыть" } }, .doc = .{ .en = "Shows (1) or hides (0) the item.", .ru = "Показывает (1) или прячет (0) предмет." } },
    .{ .name = "LEVEL_DecAdvVar", .params = "", .doc = .{ .en = "Subtracts 1 from the level progress counter (progress).", .ru = "Вычитает 1 из счётчика прогресса уровня (progress)." } },
    .{ .name = "LEVEL_GetAdvVar", .params = "", .doc = .{ .en = "Returns the level progress counter (progress), 0 if there is no level object.", .ru = "Возвращает счётчик прогресса уровня (progress), 0 если объекта уровня нет." } },
    .{ .name = "LEVEL_IncAdvVar", .params = "", .doc = .{ .en = "Adds 1 to the level progress counter (progress of the level object, saved with it).", .ru = "Прибавляет 1 к счётчику прогресса уровня (progress объекта уровня, сохраняется вместе с ним)." } },
    .{ .name = "LEVEL_Load", .params = "level level=\"05__lab_incubus\"", .docs = &.{.{ .en = "level to move to", .ru = "уровень, на который перейти" }}, .doc = .{ .en = "Queues a move to the named level. Some later calls in the same script call (`FadeIn`, `PlaceHeroes`, `DisableHeroes`) are deferred and apply to the new level.", .ru = "Ставит в очередь переход на указанный уровень. Некоторые следующие вызовы в том же вызове скрипта (`FadeIn`, `PlaceHeroes`, `DisableHeroes`) откладываются и действуют уже на новом уровне." } },
    .{ .name = "LEVEL_LoadAB", .params = "level level=\"03_museum\"", .docs = &.{.{ .en = "level to move to (gets AfterBattle)", .ru = "уровень, на который перейти (получит AfterBattle)" }}, .doc = .{ .en = "Same as `LEVEL_Load`, but the new level then gets AfterBattle(previous level name), as after a battle.", .ru = "То же, что `LEVEL_Load`, но новый уровень затем получает AfterBattle(имя прошлого уровня), как после боя." } },
    .{ .name = "LEVEL_SetAdvVar", .params = "int value=10", .docs = &.{.{ .en = "new progress counter value", .ru = "новое значение счётчика прогресса" }}, .doc = .{ .en = "Sets the level progress counter (progress).", .ru = "Задаёт счётчик прогресса уровня (progress)." } },
    .{ .name = "LinkActor", .params = "string point=\"pilot1\", string actor=\"smoke_pilot_1\"", .docs = &.{ .{ .en = "link point of the calling object's mesh", .ru = "точка связи меша вызывающего объекта" }, .{ .en = "actor riding on it", .ru = "актёр, едущий на ней" } }, .doc = .{ .en = "The actor rides the calling object at that link point of its mesh, drawn with it in its own animations (the Smoke Rider's pilots).", .ru = "Актёр едет на вызывающем объекте в этой точке связи его меша и рисуется вместе с ним в своих анимациях (пилоты Smoke Rider)." } },
    .{ .name = "NotInPlaceAnimation", .params = "string anim=\"pontA_out\"", .docs = &.{.{ .en = "animation that moves the actor", .ru = "анимация, двигающая актёра" }}, .doc = .{ .en = "Marks an animation of the current actor as moving (not in place): its offsets count from the reference animation.", .ru = "Помечает анимацию текущего актёра как смещающую (не на месте): её смещения считаются от опорной анимации." } },
    .{ .name = "PlaceActor", .params = "string name=\"Trantigne\", string area=\"capt_start\", int index=1, ?int floor=0", .docs = &.{ .{ .en = "enabled actor to place", .ru = "включённый актёр, которого поставить" }, .{ .en = "area whose point is used (or tile x)", .ru = "область, точка которой берётся (или x клетки)" }, .{ .en = "point number in the area (or tile y)", .ru = "номер точки области (или y клетки)" }, .{ .en = "floor 0 or 1 (or dir in eighths of a turn)", .ru = "этаж 0 или 1 (или направление в восьмых оборота)" } }, .doc = .{ .en = "Puts an enabled actor at point index of an area (angle from the point), on floor 0 or 1; the alternative form `PlaceActor`(name, x, y[, dir]) puts it on battle grid tile (x, y) with dir in eighths of a turn. Returns 1 if the placement was reached.", .ru = "Ставит включённого актёра в точку index области (угол берётся из точки), на этаж 0 или 1; вариант `PlaceActor`(name, x, y[, dir]) ставит на клетку боевой сетки (x, y), dir — восьмые доли оборота. Возвращает 1, если дошло до расстановки." } },
    .{ .name = "PlaceCombatActor", .params = "string actor=\"01pr_a_logs1\", float x=12.5, float y=23.0, float angle=10", .docs = &.{ .{ .en = "battle prop to place", .ru = "ставимый боевой реквизит" }, .{ .en = "fractional grid column", .ru = "дробный столбец сетки" }, .{ .en = "fractional grid row", .ru = "дробная строка сетки" }, .{ .en = "rotation in degrees", .ru = "поворот в градусах" } }, .doc = .{ .en = "Places a battle prop at a fractional grid tile (not snapped to the tile centre), rotated by angle in degrees. Returns 1 on success, 0 otherwise.", .ru = "Ставит боевой объект на дробную клетку сетки (без привязки к центру клетки), с поворотом angle в градусах. Возвращает 1 при успехе, иначе 0." } },
    .{ .name = "PlaceHeroes", .params = "string area=\"capt_start\", ?int floor=0", .docs = &.{ .{ .en = "area the heroes are placed in", .ru = "область, в которую ставятся герои" }, .{ .en = "floor 0 or 1", .ru = "этаж 0 или 1" } }, .doc = .{ .en = "Places the heroes in the area on floor 0 or 1 and snaps the camera. Returns 1; after `LEVEL_Load` it applies to the new level.", .ru = "Расставляет героев в зоне на этаже 0 или 1 и сразу переводит камеру. Возвращает 1; после `LEVEL_Load` действует на новом уровне." } },
    .{ .name = "PlayRandomSound2D", .params = "int x=936, int y=1674, string sounds=\"crow1\", ?int chance=800", .docs = &.{ .{ .en = "background x of the sound", .ru = "x звука на фоне" }, .{ .en = "background y of the sound", .ru = "y звука на фоне" }, .{ .en = "comma-separated sound names (up to 10)", .ru = "имена звуков через запятую (до 10)" }, .{ .en = ">0: plays with probability 1/chance", .ru = ">0 — играет с вероятностью 1/chance" } }, .doc = .{ .en = "Plays one sound picked at random from a comma-separated list (up to 10) at background point (x, y). With chance > 0 it plays only with probability 1/chance.", .ru = "Проигрывает в точке фона (x, y) случайный звук из списка через запятую (до 10). При chance > 0 звучит лишь с вероятностью 1/chance." } },
    .{ .name = "PlaySound", .params = "sound sound=\"opentreasure\", ?int loop=0", .docs = &.{ .{ .en = "sound name", .ru = "имя звука" }, .{ .en = "non-zero: loops", .ru = "не 0 — зациклить" } }, .doc = .{ .en = "Plays a sound at the calling object's position; non-zero loop makes it loop.", .ru = "Проигрывает звук в позиции вызывающего объекта; ненулевой loop зацикливает его." } },
    .{ .name = "print", .params = "string text=\"Hello!\"", .docs = &.{.{ .en = "written to the engine log (each argument)", .ru = "пишется в лог движка (каждый аргумент)" }}, .doc = .{ .en = "Writes each argument to the engine log, prefixed with the calling object's name. Returns 0.", .ru = "Пишет каждый аргумент в лог движка с именем вызывающего объекта. Возвращает 0." } },
    .{ .name = "PutLargeTimeBomb", .params = "int x=5, int y=8", .docs = &.{ .{ .en = "battle tile column", .ru = "столбец клетки боя" }, .{ .en = "battle tile row", .ru = "строка клетки боя" } }, .doc = .{ .en = "Places a large time bomb on the battle tile; after 6 enemy turns it explodes and everyone dies. Returns 1 if placed, 0 if the tile is off the map.", .ru = "Ставит большую бомбу с таймером на клетку боя; через 6 ходов врагов она взрывается и все гибнут. Возвращает 1, если поставлена, 0 если клетка вне карты." } },
    .{ .name = "ReferenceAnimation", .params = "string anim=\"su_idle\"", .docs = &.{.{ .en = "reference animation of the current actor", .ru = "опорная анимация текущего актёра" }}, .doc = .{ .en = "Sets the current actor's reference animation; offsets of not-in-place animations count from its first frame.", .ru = "Задаёт опорную анимацию текущего актёра; смещения анимаций не на месте отсчитываются от её первого кадра." } },
    .{ .name = "RegisterAnimation", .params = "int state=0, string logical=\"defend\", string anim=\"unik\"", .docs = &.{ .{ .en = "hold state 0..8", .ru = "стойка 0..8" }, .{ .en = "logical name the scripts use", .ru = "логическое имя, которое используют скрипты" }, .{ .en = "model animation it plays", .ru = "анимация модели, которая играет" } }, .doc = .{ .en = "Maps a logical animation name to a real animation for hold state 0..8 of the current actor.", .ru = "Сопоставляет логическое имя анимации реальной анимации для состояния 0..8 текущего актёра." } },
    .{ .name = "RegisterExtraBody", .params = "int slot=0, int still=0, string mesh=\"pila\"", .docs = &.{ .{ .en = "slot 0..3", .ru = "слот 0..3" }, .{ .en = "0: plays the actor's animations, else first frame only", .ru = "0 — играет анимации актёра, иначе только первый кадр" }, .{ .en = "mesh drawn in the slot", .ru = "меш, рисуемый в слоте" } }, .doc = .{ .en = "Gives the current actor an extra body: mesh drawn in the actor's place in slot 0…3 (replacing the slot's old one); still 0 plays the actor's animations on it, else it stays on its first frame. Types must be int, int, string. Not used by the game's scripts.", .ru = "Даёт текущему актёру дополнительное тело: меш, рисуемый на месте актёра, в слоте 0…3 (заменяет прежний); still 0 — на нём играют анимации актёра, иначе он стоит на первом кадре. Типы строго int, int, string. В скриптах игры не используется." } },
    .{ .name = "RegisterIdleAnimation", .params = "int state=0, string anim=\"idle\", int weight=100", .docs = &.{ .{ .en = "hold state 0..8", .ru = "стойка 0..8" }, .{ .en = "idle animation of the model", .ru = "idle-анимация модели" }, .{ .en = "random-pick weight", .ru = "вес случайного выбора" } }, .doc = .{ .en = "Adds an idle animation for hold state 0..8 of the current actor with a random-pick weight. Without a weight nothing is registered.", .ru = "Добавляет текущему актёру idle-анимацию для состояния 0..8 с весом случайного выбора. Без веса ничего не регистрируется." } },
    .{ .name = "s_stricmp", .params = "string a=\"05__lab_lamare\", string b=\"04__city_mfd\"", .docs = &.{ .{ .en = "first string", .ru = "первая строка" }, .{ .en = "second string", .ru = "вторая строка" } }, .doc = .{ .en = "Case-insensitive string comparison. Returns 0 if equal, otherwise the difference of the first differing characters (or of the lengths).", .ru = "Сравнивает строки без учёта регистра. Возвращает 0 при равенстве, иначе разницу первых различающихся символов (или длин)." } },
    .{ .name = "SetActorAddVariables", .params = "string actor=\"01bg_msm\", float x=-50.0, float y=10.0, float z=65.0", .docs = &.{ .{ .en = "actor whose model offset is set", .ru = "актёр, смещение модели которого задаётся" }, .{ .en = "x offset (float; else unchanged)", .ru = "смещение по x (дробное; иначе без изменений)" }, .{ .en = "y offset (float; else unchanged)", .ru = "смещение по y (дробное; иначе без изменений)" }, .{ .en = "z offset (float; else unchanged)", .ru = "смещение по z (дробное; иначе без изменений)" } }, .doc = .{ .en = "Sets the actor's model offset from its position; only float arguments change the corresponding axis.", .ru = "Задаёт смещение модели актёра от его позиции; меняются только оси, переданные как float." } },
    .{ .name = "SetActorMap", .params = "string actor=\"Sullivan\", int floor=1", .docs = &.{ .{ .en = "actor moved to the floor", .ru = "актёр, переводимый на этаж" }, .{ .en = "1: .wm2, otherwise .wm", .ru = "1 — .wm2, иначе .wm" } }, .doc = .{ .en = "Puts the actor on floor 1 (.wm2) if floor is 1, otherwise on floor 0 (.wm).", .ru = "Ставит актёра на этаж 1 (.wm2), если floor равен 1, иначе на этаж 0 (.wm)." } },
    .{ .name = "SetActorState", .params = "int state=2", .docs = &.{.{ .en = "hold state 0..8 of the current actor", .ru = "стойка 0..8 текущего актёра" }}, .doc = .{ .en = "Sets the hold state of the current actor (selects its animation set).", .ru = "Задаёт состояние текущего актёра (выбирает набор его анимаций)." } },
    .{ .name = "SetAddonScriptlet", .params = "scene scene=\"lab-enter\"", .docs = &.{.{ .en = "scene to run after the current one", .ru = "сценка, запускаемая после текущей" }}, .doc = .{ .en = "If a scene is running, queues this scene to run after it (replacing any queued one); otherwise starts it at once.", .ru = "Если идёт сцена, ставит эту сцену в очередь после неё (заменяя уже поставленную); иначе запускает сразу." } },
    .{ .name = "SetGlobalStringVariable", .params = "string name=\"HERO1\", string value=\"Sullivan\"", .docs = &.{ .{ .en = "variable name (ignored by the port)", .ru = "имя переменной (порт игнорирует)" }, .{ .en = "value (ignored by the port)", .ru = "значение (порт игнорирует)" } }, .doc = .{ .en = "No-op in this port: the game's scenes only read #HERO_SELECTED and #LAST_ACTION_HERO, which come from world state.", .ru = "В порте ничего не делает: сцены игры читают только #HERO_SELECTED и #LAST_ACTION_HERO, а они берутся из состояния мира." } },
    .{ .name = "Signature", .params = "int frame=1", .docs = &.{.{ .en = "intro.spr frame; -1 removes it", .ru = "кадр intro.spr; -1 — убрать" }}, .doc = .{ .en = "Shows a date caption (frame of intro.spr) at the bottom of the screen; -1 removes it.", .ru = "Показывает подпись с датой (кадр intro.spr) внизу экрана; -1 убирает её." } },
    .{ .name = "StartScriptlet", .params = "scene scene=\"port-silos\"", .docs = &.{.{ .en = "scene to start", .ru = "запускаемая сценка" }}, .doc = .{ .en = "Starts the named scene (scriptlet) at once.", .ru = "Сразу запускает сцену (скриптлет) с этим именем." } },
    .{ .name = "StopActor", .params = "string actor=\"ponton\"", .docs = &.{.{ .en = "actor to stop", .ru = "останавливаемый актёр" }}, .doc = .{ .en = "Stops the actor: clears its command queue, path and current command.", .ru = "Останавливает актёра: очищает очередь команд, путь и текущую команду." } },
    .{ .name = "str", .params = "any value=5", .docs = &.{.{ .en = "any value", .ru = "любое значение" }}, .doc = .{ .en = "OpenGorky only (the original exe has no such function): the value as text, for joining strings with +: a number as a string variable takes it (5 → \"5\", 2.5 → \"2.500000\"), true/false, nil → \"nil\", an object → its name, a list or map as written ([1, \"a\"]).", .ru = "Только OpenGorky (в оригинальном exe такой функции нет): значение текстом, для склейки строк через +: число — как его принимает строковая переменная (5 → \"5\", 2.5 → \"2.500000\"), true/false, nil → \"nil\", объект — его имя, список и словарь — как записаны ([1, \"a\"])." } },
    .{ .name = "Subscribe", .params = "string event=\"child_died\", method handler=\"OnChildDied\"", .docs = &.{ .{ .en = "event name", .ru = "имя события" }, .{ .en = "the calling component's method that hears it (checked when the code is linked)", .ru = "метод вызывающего компонента, который его услышит (проверяется при связывании)" } }, .doc = .{ .en = "OpenGorky only (the original exe has no such function), for a fighter's scripted abilities and other components: from a component's method: when the event is emitted (`Emit`), this component calls its method handler with the event's values. True if subscribed now, false if it already was. The subscription ends with `Unsubscribe` or when the component is detached.", .ru = "Только OpenGorky (в оригинальном exe такой функции нет), для скриптовых способностей бойца и других компонентов: из метода компонента: когда событие отправлено (`Emit`), этот компонент вызывает свой метод handler со значениями события. true — подписан сейчас, false — уже был. Подписка кончается с `Unsubscribe` или когда компонент отключён." } },
