/// The original exe's builtins: its 117 registrations (`call 0x4c2270`, name → handler),
/// in its order. A function in `all` missing here works only in the port.
const exe_names = [_][]const u8{
    "print",                      "FighterGetHp",              "FighterSetHp",               "FighterSetLevel",         "FighterSetWeaponSkillLevel",     "EndTurnGlobal",
    "FadeIn",                     "PutLargeTimeBomb",          "AIEnemyAppear",              "AIFreeTile",              "AITargetLock",                   "AIGuardPoint",
    "AIGetTurnNo",                "SetActorAddVariables",      "AllowWalkInArea",            "ForbidWalkInArea",        "TestActorMapChange",             "SetActorMap",
    "PlaceActor",                 "PlaceHeroes",               "PlaceCombatActor",           "RegisterIdleAnimation",   "RegisterAnimation",              "RegisterExtraBody",
    "ActorInArea",                "StartScriptlet",            "SetAddonScriptlet",          "SetActorState",           "ActivateLink",                   "DeactivateLink",
    "SetGlobalStringVariable",    "AttachActors",              "AttachActorsByLink",         "ActorDelay",              "ActorAnimation",                 "ActorAsyncAnimation",
    "ActorAsyncWalkAnimation",    "ActorModifyScale",          "ActorAdjustAngle",           "ActorSetWalkAnimation",   "ActorQueueWalkAnimation",        "ActorSetWalkSpeed",
    "ActorEnableRotation",        "ActorDisableInterpolation", "ActorQueueWaitForAnimation", "ActorQueueDelay",         "ActorQueueWaitForInterpolation", "ActorPutBackItem",
    "ActorPutFrontItem",          "WalkOnSceneryTrack",        "Vibrato",                    "HeroInArea",              "DetachActorsFrom",               "ABA_Impulse",
    "LEVEL_Load",                 "LEVEL_LoadAB",              "LEVEL_IncAdvVar",            "LEVEL_DecAdvVar",         "LEVEL_SetAdvVar",                "LEVEL_GetAdvVar",
    "EnableObject",               "DisableObject",             "Disable",                    "DeleteObject",            "s_stricmp",                      "StopActor",
    "GetNameID",                  "Actor_SetState",            "Actor_SetAnimation",         "Actor_SetAsyncAnimation", "Actor_QueueDelay",               "Actor_QueueState",
    "Actor_QueueJustifyPosition", "Actor_QueuePlace",          "Actor_QueueGOScriptFunc",    "Actor_GORunFun",          "Actor_ActivateLink",             "Actor_DeactivateAllLinks",
    "Actor_HaveAmmoForWeapon",    "Actor_TextEffect",          "AnyHero_HaveAmmoForWeapon",  "AnyHero_HaveItem",        "Item_SetPlace",                  "Item_SetNameID",
    "Item_SetPos",                "Item_SetAngle",             "Item_SetFuncID",             "Item_SetVisible",         "Item_GetType",                   "Item_GetNameID",
    "Item_GetPlace",              "Item_Animation",            "Item_EnableWalkCircle",      "Item_DisableWalkCircle",  "Weapon_New",                     "Item_New",
    "Ambient_New",                "Signature",                 "IsObject",                   "DialogInit",              "AdjustAngle",                    "GUI_Panorama",
    "GUI_Disable",                "GUI_SelectMode",            "GUI_GetSelectedHero",        "GUI_IsHero",              "ReferenceAnimation",             "NotInPlaceAnimation",
    "HERO_EnableEnumerate",       "EnableHeroes",              "DisableHeroes",              "PlaySound",               "PlayRandomSound2D",              "LinkActor",
    "GO_RunFun",                  "GetName",                   "AVI_Play",
};

/// Whether the original exe registers `name` (its calls ignore case).
fn inExe(name: []const u8) bool {
    for (exe_names) |n| if (std.ascii.eqlIgnoreCase(n, name)) return true;
    return false;
}

/// A port-only extension: the port runs it, the original exe does not know it.
pub fn portOnly(f: *const Fn) bool {
    return !inExe(f.name);
}

/// Whether the port or the exe registers `name` (a call to anything else, not defined in
/// the scripts either, does nothing in both).
pub fn known(name: []const u8) bool {
    return find(name) != null or inExe(name);
}

/// Whether an earlier entry has `f`'s OG Script name (ActorQueueDelay: `path::Delay`, as
/// ActorDelay): OG Script has one function for both.
pub fn ogsTwin(f: *const Fn) bool {
    const o = ogsName(f);
    if (o.len == 0) return false;
    for (all[0 .. f - &all[0]]) |*e| if (std.mem.eql(u8, ogsName(e), o)) return true;
    return false;
}

/// The exe's names of every entry OG Script calls `o` (`ActorDelay, ActorQueueDelay`).
pub fn classicNames(a: Allocator, o: []const u8) []const u8 {
    var out: std.ArrayList(u8) = .empty;
    for (&all) |*f| if (std.mem.eql(u8, ogsName(f), o)) out.print(a, "{s}{s}", .{ if (out.items.len > 0) ", " else "", f.name }) catch {};
    return out.items;
}

test "api: builtins sharing an OG Script name" {
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();
    try std.testing.expect(!ogsTwin(find("ActorDelay").?) and ogsTwin(find("ActorQueueDelay").?) and !ogsTwin(find("GetName").?));
    try std.testing.expectEqualStrings("ActorDelay, ActorQueueDelay", classicNames(arena.allocator(), "path::Delay"));
}

test "api: OG Script's names from the builtins' table" {
    try std.testing.expectEqualStrings("fighter::SetHp", ogsName(find("FighterSetHp").?));
    try std.testing.expectEqual(find("FighterSetHp").?, find("fighter::SetHp").?);
    try std.testing.expectEqualStrings("path::Delay", ogsName(find("ActorQueueDelay").?));
    try std.testing.expectEqualStrings("print", ogsName(find("print").?));
    try std.testing.expectEqualStrings("", ogsName(find("GetName").?));
    try std.testing.expectEqualStrings("item", package(find("Item_New").?));
    try std.testing.expect(find("SetHp") == null);
}

test "api: every entry's parameters parse" {
    var buf: [12]Param = undefined;
    for (&all) |*f| {
        var seen_opt = false;
        for (params(f, &buf)) |p| {
            try std.testing.expect(std.mem.indexOfScalar(u8, p.decl, ' ') != null);
            if (seen_opt) try std.testing.expect(p.optional);
            seen_opt = seen_opt or p.optional;
        }
        try std.testing.expect(f.doc.en.len > 0 and f.doc.ru.len > 0);
    }
}

test "api: every parameter has its description in both languages" {
    var buf: [12]Param = undefined;
    for (&all) |*f| {
        const ps = params(f, &buf);
        if (f.docs.len != ps.len) std.debug.print("api.zig: {s} has {d} parameters, {d} descriptions\n", .{ f.name, ps.len, f.docs.len });
        try std.testing.expectEqual(ps.len, f.docs.len);
        for (ps) |p| try std.testing.expect(p.doc.en.len > 0 and p.doc.ru.len > 0);
    }
}

test "api: one entry per builtin the port registers (src/builtins.zig), no others" {
    const src = @embedFile("builtins_src");
    var n: usize = 0;
    var pos: usize = 0;
    while (std.mem.indexOfPos(u8, src, pos, ".{ \"")) |i| {
        const a = i + 4;
        const e = std.mem.indexOfScalarPos(u8, src, a, '"') orelse break;
        pos = e;
        if (find(src[a..e]) == null) std.debug.print("api.zig: no entry for builtin {s}\n", .{src[a..e]});
        try std.testing.expect(find(src[a..e]) != null);
        n += 1;
    }
    try std.testing.expectEqual(all.len, n);
}

test "api: port-only builtins are the ones the exe lacks (GetClass, GetLevel, str, Dialog, the battle's scripted abilities)" {
    for (&all) |*f| try std.testing.expectEqual(std.ascii.eqlIgnoreCase(f.name, "GetClass") or std.ascii.eqlIgnoreCase(f.name, "GetLevel") or std.mem.eql(u8, f.name, "str") or std.mem.eql(u8, f.name, "EqualsIgnoreCase") or std.mem.eql(u8, f.name, "IsHere") or std.mem.eql(u8, f.name, "Dialog") or
        std.mem.startsWith(u8, f.doc.en, "OpenGorky only (the original exe has no such function), for a fighter's"), portOnly(f));
}

test "api: parameter types match the builtins' signatures (src/builtins.zig)" {
    var buf: [12]Param = undefined;
    var text: [256]u8 = undefined;
    inline for (@import("opengorky").builtins.table) |e| {
        var w: std.Io.Writer = .fixed(&text);
        for (params(find(e[0]).?, &buf), 0..) |p, i| {
            const ty = p.decl[0 .. std.mem.indexOfScalar(u8, p.decl, ' ') orelse p.decl.len];
            try w.print("{s}{s}{s}", .{ if (i > 0) ", " else "", if (p.optional) "?" else "", ty });
        }
        // The signature's types (a parameter's name after its type left out).
        const sig: []const u8 = e[2].text;
        const open = std.mem.indexOfScalar(u8, sig, '(').?;
        var types: [256]u8 = undefined;
        var tw: std.Io.Writer = .fixed(&types);
        var it = std.mem.splitSequence(u8, sig[open + 1 .. sig.len - 1], ", ");
        var k: usize = 0;
        while (it.next()) |p| : (k += 1) if (p.len > 0) try tw.print("{s}{s}", .{ if (k > 0) ", " else "", p[0 .. std.mem.indexOfScalar(u8, p, ' ') orelse p.len] });
        if (!std.mem.eql(u8, tw.buffered(), w.buffered())) std.debug.print("api.zig: {s} has ({s}), builtins.zig {s}\n", .{ e[0], w.buffered(), sig });
        try std.testing.expectEqualStrings(tw.buffered(), w.buffered());
    }
}

test "backticked names in descriptions are builtins; OG shows their package names" {
    for (all) |f| for (0..f.docs.len + 1) |d| {
        const m = if (d == 0) f.doc else f.docs[d - 1];
        for ([_][]const u8{ m.en, m.ru }) |t| {
            var it = std.mem.splitScalar(u8, t, '`');
            var k: usize = 0;
            while (it.next()) |w| : (k += 1) if (k % 2 == 1 and w.len > 0 and std.ascii.isUpper(w[0]) and std.mem.indexOfAny(u8, w, " :.") == null)
                if (find(w) == null) {
                    std.debug.print("{s}: unknown `{s}`\n", .{ f.name, w });
                    return error.UnknownBuiltin;
                };
        }
    };
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const s = "before `LEVEL_Load` and `x`";
    try std.testing.expect(std.mem.indexOf(u8, docText(arena.allocator(), s, true), "level::") != null);
    try std.testing.expectEqualStrings("before LEVEL_Load and `x`", docText(arena.allocator(), s, false));
}
